mkitem!{mkstruct!{#[doc = " A lifetime. The valid field combinations are non-obvious and not all"] #[doc = " combinations are possible. The following example shows some of"] #[doc = " them. See also the comments on `LifetimeKind` and `LifetimeSource`."] #[doc = ""] #[doc = " ```"] #[doc = " #[repr(C)]"] #[doc = " struct S<'a>(&'a u32);       // res=Param, name='a, source=Reference, syntax=ExplicitBound"] #[doc = " unsafe extern \"C\" {"] #[doc = "     fn f1(s: S);             // res=Param, name='_, source=Path, syntax=Implicit"] #[doc = "     fn f2(s: S<'_>);         // res=Param, name='_, source=Path, syntax=ExplicitAnonymous"] #[doc = "     fn f3<'a>(s: S<'a>);     // res=Param, name='a, source=Path, syntax=ExplicitBound"] #[doc = " }"] #[doc = ""] #[doc = " struct St<'a> { x: &'a u32 } // res=Param, name='a, source=Reference, syntax=ExplicitBound"] #[doc = " fn f() {"] #[doc = "     _ = St { x: &0 };        // res=Infer, name='_, source=Path, syntax=Implicit"] #[doc = "     _ = St::<'_> { x: &0 };  // res=Infer, name='_, source=Path, syntax=ExplicitAnonymous"] #[doc = " }"] #[doc = ""] #[doc = " struct Name<'a>(&'a str);    // res=Param,  name='a, source=Reference, syntax=ExplicitBound"] #[doc = " const A: Name = Name(\"a\");   // res=Static, name='_, source=Path, syntax=Implicit"] #[doc = " const B: &str = \"\";          // res=Static, name='_, source=Reference, syntax=Implicit"] #[doc = " static C: &'_ str = \"\";      // res=Static, name='_, source=Reference, syntax=ExplicitAnonymous"] #[doc = " static D: &'static str = \"\"; // res=Static, name='static, source=Reference, syntax=ExplicitBound"] #[doc = ""] #[doc = " trait Tr {}"] #[doc = " fn tr(_: Box<dyn Tr>) {}     // res=ImplicitObjectLifetimeDefault, name='_, source=Other, syntax=Implicit"] #[doc = ""] #[doc = " fn capture_outlives<'a>() ->"] #[doc = "     impl FnOnce() + 'a       // res=Param, ident='a, source=OutlivesBound, syntax=ExplicitBound"] #[doc = " {"] #[doc = "     || {}"] #[doc = " }"] #[doc = ""] #[doc = " fn capture_precise<'a>() ->"] #[doc = "     impl FnOnce() + use<'a>  // res=Param, ident='a, source=PreciseCapturing, syntax=ExplicitBound"] #[doc = " {"] #[doc = "     || {}"] #[doc = " }"] #[doc = ""] #[doc = " // (commented out because these cases trigger errors)"] #[doc = " // struct S1<'a>(&'a str);   // res=Param, name='a, source=Reference, syntax=ExplicitBound"] #[doc = " // struct S2(S1);            // res=Error, name='_, source=Path, syntax=Implicit"] #[doc = " // struct S3(S1<'_>);        // res=Error, name='_, source=Path, syntax=ExplicitAnonymous"] #[doc = " // struct S4(S1<'a>);        // res=Error, name='a, source=Path, syntax=ExplicitBound"] #[doc = " ```"] #[doc = ""] #[doc = " Some combinations that cannot occur are `LifetimeSyntax::Implicit` with"] #[doc = " `LifetimeSource::OutlivesBound` or `LifetimeSource::PreciseCapturing`"] #[doc = " — there's no way to \"elide\" these lifetimes."] #[derive (Debug , Copy , Clone , HashStable_Generic)] #[repr (align (4))] pub struct Lifetime { #[stable_hasher (ignore)] pub hir_id : HirId , #[doc = " Either a named lifetime definition (e.g. `'a`, `'static`) or an"] #[doc = " anonymous lifetime (`'_`, either explicitly written, or inserted for"] #[doc = " things like `&type`)."] pub ident : Ident , #[doc = " Semantics of this lifetime."] pub kind : LifetimeKind , #[doc = " The context in which the lifetime occurred. See `Lifetime::suggestion`"] #[doc = " for example use."] pub source : LifetimeSource , #[doc = " The syntax that the user used to declare this lifetime. See"] #[doc = " `Lifetime::suggestion` for example use."] pub syntax : LifetimeSyntax , }}}
mkitem!{mkenum!{#[derive (Debug , Copy , Clone , HashStable_Generic)] pub enum ParamName { #[doc = " Some user-given name like `T` or `'x`."] Plain (Ident) , #[doc = " Indicates an illegal name was given and an error has been"] #[doc = " reported (so we should squelch other derived errors)."] #[doc = ""] #[doc = " Occurs when, e.g., `'_` is used in the wrong place, or a"] #[doc = " lifetime name is duplicated."] Error (Ident) , #[doc = " Synthetic name generated when user elided a lifetime in an impl header."] #[doc = ""] #[doc = " E.g., the lifetimes in cases like these:"] #[doc = " ```ignore (fragment)"] #[doc = " impl Foo for &u32"] #[doc = " impl Foo<'_> for u32"] #[doc = " ```"] #[doc = " in that case, we rewrite to"] #[doc = " ```ignore (fragment)"] #[doc = " impl<'f> Foo for &'f u32"] #[doc = " impl<'f> Foo<'f> for u32"] #[doc = " ```"] #[doc = " where `'f` is something like `Fresh(0)`. The indices are"] #[doc = " unique per impl, but not necessarily continuous."] Fresh , }}}
mkitem!{mkimpl!{impl ParamName { pub fn ident (& self) -> Ident { match * self { ParamName :: Plain (ident) | ParamName :: Error (ident) => ident , ParamName :: Fresh => Ident :: with_dummy_span (kw :: UnderscoreLifetime) , } } }}}
mkitem!{mkenum!{#[derive (Debug , Copy , Clone , PartialEq , Eq , Hash , HashStable_Generic)] pub enum LifetimeKind { #[doc = " User-given names or fresh (synthetic) names."] Param (LocalDefId) , #[doc = " Implicit lifetime in a context like `dyn Foo`. This is"] #[doc = " distinguished from implicit lifetimes elsewhere because the"] #[doc = " lifetime that they default to must appear elsewhere within the"] #[doc = " enclosing type. This means that, in an `impl Trait` context, we"] #[doc = " don't have to create a parameter for them. That is, `impl"] #[doc = " Trait<Item = &u32>` expands to an opaque type like `type"] #[doc = " Foo<'a> = impl Trait<Item = &'a u32>`, but `impl Trait<item ="] #[doc = " dyn Bar>` expands to `type Foo = impl Trait<Item = dyn Bar +"] #[doc = " 'static>`. The latter uses `ImplicitObjectLifetimeDefault` so"] #[doc = " that surrounding code knows not to create a lifetime"] #[doc = " parameter."] ImplicitObjectLifetimeDefault , #[doc = " Indicates an error during lowering (usually `'_` in wrong place)"] #[doc = " that was already reported."] Error , #[doc = " User wrote an anonymous lifetime, either `'_` or nothing (which gets"] #[doc = " converted to `'_`). The semantics of this lifetime should be inferred"] #[doc = " by typechecking code."] Infer , #[doc = " User wrote `'static` or nothing (which gets converted to `'_`)."] Static , }}}
mkitem!{mkimpl!{impl LifetimeKind { fn is_elided (& self) -> bool { match self { LifetimeKind :: ImplicitObjectLifetimeDefault | LifetimeKind :: Infer => true , LifetimeKind :: Error | LifetimeKind :: Param (..) | LifetimeKind :: Static => false , } } }}}
mkitem!{mkimpl!{impl fmt :: Display for Lifetime { fn fmt (& self , f : & mut fmt :: Formatter < '_ >) -> fmt :: Result { self . ident . name . fmt (f) } }}}
mkitem!{mkimpl!{impl Lifetime { pub fn new (hir_id : HirId , ident : Ident , kind : LifetimeKind , source : LifetimeSource , syntax : LifetimeSyntax ,) -> Lifetime { let lifetime = Lifetime { hir_id , ident , kind , source , syntax } ; #[cfg (debug_assertions)] match (lifetime . is_elided () , lifetime . is_anonymous ()) { (false , false) => { } (false , true) => { } (true , true) => { } (true , false) => panic ! ("bad Lifetime") , } lifetime } pub fn is_elided (& self) -> bool { self . kind . is_elided () } pub fn is_anonymous (& self) -> bool { self . ident . name == kw :: UnderscoreLifetime } pub fn is_implicit (& self) -> bool { matches ! (self . syntax , LifetimeSyntax :: Implicit) } pub fn is_static (& self) -> bool { self . kind == LifetimeKind :: Static } pub fn suggestion (& self , new_lifetime : & str) -> (Span , String) { use LifetimeSource :: * ; use LifetimeSyntax :: * ; debug_assert ! (new_lifetime . starts_with ('\'')) ; match (self . syntax , self . source) { (ExplicitBound | ExplicitAnonymous , _) => (self . ident . span , format ! ("{new_lifetime}")) , (Implicit , Path { angle_brackets : AngleBrackets :: Full }) => { (self . ident . span , format ! ("{new_lifetime}, ")) } (Implicit , Path { angle_brackets : AngleBrackets :: Empty }) => { (self . ident . span , format ! ("{new_lifetime}")) } (Implicit , Path { angle_brackets : AngleBrackets :: Missing }) => { (self . ident . span . shrink_to_hi () , format ! ("<{new_lifetime}>")) } (Implicit , Reference) => (self . ident . span , format ! ("{new_lifetime} ")) , (Implicit , source) => { unreachable ! ("can't suggest for a implicit lifetime of {source:?}") } } } }}}
mkitem!{mkstruct!{#[doc = " A `Path` is essentially Rust's notion of a name; for instance,"] #[doc = " `std::cmp::PartialEq`. It's represented as a sequence of identifiers,"] #[doc = " along with a bunch of supporting information."] #[derive (Debug , Clone , Copy , HashStable_Generic)] pub struct Path < 'hir , R = Res > { pub span : Span , #[doc = " The resolution for the path."] pub res : R , #[doc = " The segments in the path: the things separated by `::`."] pub segments : & 'hir [PathSegment < 'hir >] , }}}
mkitem!{#[doc = " Up to three resolutions for type, value and macro namespaces."] pub type UsePath < 'hir > = Path < 'hir , PerNS < Option < Res > > > ;}
mkitem!{mkimpl!{impl Path < '_ > { pub fn is_global (& self) -> bool { self . segments . first () . is_some_and (| segment | segment . ident . name == kw :: PathRoot) } }}}
mkitem!{mkstruct!{#[doc = " A segment of a path: an identifier, an optional lifetime, and a set of"] #[doc = " types."] #[derive (Debug , Clone , Copy , HashStable_Generic)] pub struct PathSegment < 'hir > { #[doc = " The identifier portion of this path segment."] pub ident : Ident , #[stable_hasher (ignore)] pub hir_id : HirId , pub res : Res , #[doc = " Type/lifetime parameters attached to this path. They come in"] #[doc = " two flavors: `Path<A,B,C>` and `Path(A,B) -> C`. Note that"] #[doc = " this is more than just simple syntactic sugar; the use of"] #[doc = " parens affects the region binding rules, so we preserve the"] #[doc = " distinction."] pub args : Option < & 'hir GenericArgs < 'hir > > , #[doc = " Whether to infer remaining type parameters, if any."] #[doc = " This only applies to expression and pattern paths, and"] #[doc = " out of those only the segments with no type parameters"] #[doc = " to begin with, e.g., `Vec::new` is `<Vec<..>>::new::<..>`."] pub infer_args : bool , }}}
mkitem!{mkimpl!{impl < 'hir > PathSegment < 'hir > { #[doc = " Converts an identifier to the corresponding segment."] pub fn new (ident : Ident , hir_id : HirId , res : Res) -> PathSegment < 'hir > { PathSegment { ident , hir_id , res , infer_args : true , args : None } } pub fn invalid () -> Self { Self :: new (Ident :: dummy () , HirId :: INVALID , Res :: Err) } pub fn args (& self) -> & GenericArgs < 'hir > { if let Some (ref args) = self . args { args } else { const DUMMY : & GenericArgs < '_ > = & GenericArgs :: none () ; DUMMY } } }}}
mkitem!{mkstruct!{#[doc = " A constant that enters the type system, used for arguments to const generics (e.g. array lengths)."] #[doc = ""] #[doc = " These are distinct from [`AnonConst`] as anon consts in the type system are not allowed"] #[doc = " to use any generic parameters, therefore we must represent `N` differently. Additionally"] #[doc = " future designs for supporting generic parameters in const arguments will likely not use"] #[doc = " an anon const based design."] #[doc = ""] #[doc = " So, `ConstArg` (specifically, [`ConstArgKind`]) distinguishes between const args"] #[doc = " that are [just paths](ConstArgKind::Path) (currently just bare const params)"] #[doc = " versus const args that are literals or have arbitrary computations (e.g., `{ 1 + 3 }`)."] #[doc = ""] #[doc = " For an explanation of the `Unambig` generic parameter see the dev-guide:"] #[doc = " <https://rustc-dev-guide.rust-lang.org/hir/ambig-unambig-ty-and-consts.html>"] #[derive (Clone , Copy , Debug , HashStable_Generic)] #[repr (C)] pub struct ConstArg < 'hir , Unambig = () > { #[stable_hasher (ignore)] pub hir_id : HirId , pub kind : ConstArgKind < 'hir , Unambig > , }}}
mkitem!{mkimpl!{impl < 'hir > ConstArg < 'hir , AmbigArg > { #[doc = " Converts a `ConstArg` in an ambiguous position to one in an unambiguous position."] #[doc = ""] #[doc = " Functions accepting unambiguous consts may expect the [`ConstArgKind::Infer`] variant"] #[doc = " to be used. Care should be taken to separately handle infer consts when calling this"] #[doc = " function as it cannot be handled by downstream code making use of the returned const."] #[doc = ""] #[doc = " In practice this may mean overriding the [`Visitor::visit_infer`][visit_infer] method on hir visitors, or"] #[doc = " specifically matching on [`GenericArg::Infer`] when handling generic arguments."] #[doc = ""] #[doc = " [visit_infer]: [rustc_hir::intravisit::Visitor::visit_infer]"] pub fn as_unambig_ct (& self) -> & ConstArg < 'hir > { let ptr = self as * const ConstArg < 'hir , AmbigArg > as * const ConstArg < 'hir , () > ; unsafe { & * ptr } } }}}
mkitem!{mkimpl!{impl < 'hir > ConstArg < 'hir > { #[doc = " Converts a `ConstArg` in an unambiguous position to one in an ambiguous position. This is"] #[doc = " fallible as the [`ConstArgKind::Infer`] variant is not present in ambiguous positions."] #[doc = ""] #[doc = " Functions accepting ambiguous consts will not handle the [`ConstArgKind::Infer`] variant, if"] #[doc = " infer consts are relevant to you then care should be taken to handle them separately."] pub fn try_as_ambig_ct (& self) -> Option < & ConstArg < 'hir , AmbigArg > > { if let ConstArgKind :: Infer (_ , ()) = self . kind { return None ; } let ptr = self as * const ConstArg < 'hir > as * const ConstArg < 'hir , AmbigArg > ; Some (unsafe { & * ptr }) } }}}
mkitem!{mkimpl!{impl < 'hir , Unambig > ConstArg < 'hir , Unambig > { pub fn anon_const_hir_id (& self) -> Option < HirId > { match self . kind { ConstArgKind :: Anon (ac) => Some (ac . hir_id) , _ => None , } } pub fn span (& self) -> Span { match self . kind { ConstArgKind :: Path (path) => path . span () , ConstArgKind :: Anon (anon) => anon . span , ConstArgKind :: Infer (span , _) => span , } } }}}
mkitem!{mkenum!{#[doc = " See [`ConstArg`]."] #[derive (Clone , Copy , Debug , HashStable_Generic)] #[repr (u8 , C)] pub enum ConstArgKind < 'hir , Unambig = () > { #[doc = " **Note:** Currently this is only used for bare const params"] #[doc = " (`N` where `fn foo<const N: usize>(...)`),"] #[doc = " not paths to any const (`N` where `const N: usize = ...`)."] #[doc = ""] #[doc = " However, in the future, we'll be using it for all of those."] Path (QPath < 'hir >) , Anon (& 'hir AnonConst) , #[doc = " This variant is not always used to represent inference consts, sometimes"] #[doc = " [`GenericArg::Infer`] is used instead."] Infer (Span , Unambig) , }}}
mkitem!{mkstruct!{#[derive (Clone , Copy , Debug , HashStable_Generic)] pub struct InferArg { #[stable_hasher (ignore)] pub hir_id : HirId , pub span : Span , }}}
mkitem!{mkimpl!{impl InferArg { pub fn to_ty (& self) -> Ty < 'static > { Ty { kind : TyKind :: Infer (()) , span : self . span , hir_id : self . hir_id } } }}}
mkitem!{mkenum!{#[derive (Debug , Clone , Copy , HashStable_Generic)] pub enum GenericArg < 'hir > { Lifetime (& 'hir Lifetime) , Type (& 'hir Ty < 'hir , AmbigArg >) , Const (& 'hir ConstArg < 'hir , AmbigArg >) , #[doc = " Inference variables in [`GenericArg`] are always represented by"] #[doc = " `GenericArg::Infer` instead of the `Infer` variants on [`TyKind`] and"] #[doc = " [`ConstArgKind`] as it is not clear until hir ty lowering whether a"] #[doc = " `_` argument is a type or const argument."] #[doc = ""] #[doc = " However, some builtin types' generic arguments are represented by [`TyKind`]"] #[doc = " without a [`GenericArg`], instead directly storing a [`Ty`] or [`ConstArg`]. In"] #[doc = " such cases they *are* represented by the `Infer` variants on [`TyKind`] and"] #[doc = " [`ConstArgKind`] as it is not ambiguous whether the argument is a type or const."] Infer (InferArg) , }}}
mkitem!{mkimpl!{impl GenericArg < '_ > { pub fn span (& self) -> Span { match self { GenericArg :: Lifetime (l) => l . ident . span , GenericArg :: Type (t) => t . span , GenericArg :: Const (c) => c . span () , GenericArg :: Infer (i) => i . span , } } pub fn hir_id (& self) -> HirId { match self { GenericArg :: Lifetime (l) => l . hir_id , GenericArg :: Type (t) => t . hir_id , GenericArg :: Const (c) => c . hir_id , GenericArg :: Infer (i) => i . hir_id , } } pub fn descr (& self) -> & 'static str { match self { GenericArg :: Lifetime (_) => "lifetime" , GenericArg :: Type (_) => "type" , GenericArg :: Const (_) => "constant" , GenericArg :: Infer (_) => "placeholder" , } } pub fn to_ord (& self) -> ast :: ParamKindOrd { match self { GenericArg :: Lifetime (_) => ast :: ParamKindOrd :: Lifetime , GenericArg :: Type (_) | GenericArg :: Const (_) | GenericArg :: Infer (_) => { ast :: ParamKindOrd :: TypeOrConst } } } pub fn is_ty_or_const (& self) -> bool { match self { GenericArg :: Lifetime (_) => false , GenericArg :: Type (_) | GenericArg :: Const (_) | GenericArg :: Infer (_) => true , } } }}}
mkitem!{mkstruct!{#[doc = " The generic arguments and associated item constraints of a path segment."] #[derive (Debug , Clone , Copy , HashStable_Generic)] pub struct GenericArgs < 'hir > { #[doc = " The generic arguments for this path segment."] pub args : & 'hir [GenericArg < 'hir >] , #[doc = " The associated item constraints for this path segment."] pub constraints : & 'hir [AssocItemConstraint < 'hir >] , #[doc = " Whether the arguments were written in parenthesized form (e.g., `Fn(T) -> U`)."] #[doc = ""] #[doc = " This is required mostly for pretty-printing and diagnostics,"] #[doc = " but also for changing lifetime elision rules to be \"function-like\"."] pub parenthesized : GenericArgsParentheses , #[doc = " The span encompassing the arguments, constraints and the surrounding brackets (`<>` or `()`)."] #[doc = ""] #[doc = " For example:"] #[doc = ""] #[doc = " ```ignore (illustrative)"] #[doc = "       Foo<A, B, AssocTy = D>           Fn(T, U, V) -> W"] #[doc = "          ^^^^^^^^^^^^^^^^^^^             ^^^^^^^^^"] #[doc = " ```"] #[doc = ""] #[doc = " Note that this may be:"] #[doc = " - empty, if there are no generic brackets (but there may be hidden lifetimes)"] #[doc = " - dummy, if this was generated during desugaring"] pub span_ext : Span , }}}
mkitem!{mkimpl!{impl < 'hir > GenericArgs < 'hir > { pub const fn none () -> Self { Self { args : & [] , constraints : & [] , parenthesized : GenericArgsParentheses :: No , span_ext : DUMMY_SP , } } #[doc = " Obtain the list of input types and the output type if the generic arguments are parenthesized."] #[doc = ""] #[doc = " Returns the `Ty0, Ty1, ...` and the `RetTy` in `Trait(Ty0, Ty1, ...) -> RetTy`."] #[doc = " Panics if the parenthesized arguments have an incorrect form (this shouldn't happen)."] pub fn paren_sugar_inputs_output (& self) -> Option < (& [Ty < 'hir >] , & Ty < 'hir >) > { if self . parenthesized != GenericArgsParentheses :: ParenSugar { return None ; } let inputs = self . args . iter () . find_map (| arg | { let GenericArg :: Type (ty) = arg else { return None } ; let TyKind :: Tup (tys) = & ty . kind else { return None } ; Some (tys) }) . unwrap () ; Some ((inputs , self . paren_sugar_output_inner ())) } #[doc = " Obtain the output type if the generic arguments are parenthesized."] #[doc = ""] #[doc = " Returns the `RetTy` in `Trait(Ty0, Ty1, ...) -> RetTy`."] #[doc = " Panics if the parenthesized arguments have an incorrect form (this shouldn't happen)."] pub fn paren_sugar_output (& self) -> Option < & Ty < 'hir > > { (self . parenthesized == GenericArgsParentheses :: ParenSugar) . then (| | self . paren_sugar_output_inner ()) } fn paren_sugar_output_inner (& self) -> & Ty < 'hir > { let [constraint] = self . constraints . try_into () . unwrap () ; debug_assert_eq ! (constraint . ident . name , sym :: Output) ; constraint . ty () . unwrap () } pub fn has_err (& self) -> Option < ErrorGuaranteed > { self . args . iter () . find_map (| arg | { let GenericArg :: Type (ty) = arg else { return None } ; let TyKind :: Err (guar) = ty . kind else { return None } ; Some (guar) }) . or_else (| | { self . constraints . iter () . find_map (| constraint | { let TyKind :: Err (guar) = constraint . ty () ? . kind else { return None } ; Some (guar) }) }) } #[inline] pub fn num_lifetime_params (& self) -> usize { self . args . iter () . filter (| arg | matches ! (arg , GenericArg :: Lifetime (_))) . count () } #[inline] pub fn has_lifetime_params (& self) -> bool { self . args . iter () . any (| arg | matches ! (arg , GenericArg :: Lifetime (_))) } #[inline] #[doc = " This function returns the number of type and const generic params."] #[doc = " It should only be used for diagnostics."] pub fn num_generic_params (& self) -> usize { self . args . iter () . filter (| arg | ! matches ! (arg , GenericArg :: Lifetime (_))) . count () } #[doc = " The span encompassing the arguments and constraints[^1] inside the surrounding brackets."] #[doc = ""] #[doc = " Returns `None` if the span is empty (i.e., no brackets) or dummy."] #[doc = ""] #[doc = " [^1]: Unless of the form `-> Ty` (see [`GenericArgsParentheses`])."] pub fn span (& self) -> Option < Span > { let span_ext = self . span_ext () ? ; Some (span_ext . with_lo (span_ext . lo () + BytePos (1)) . with_hi (span_ext . hi () - BytePos (1))) } #[doc = " Returns span encompassing arguments and their surrounding `<>` or `()`"] pub fn span_ext (& self) -> Option < Span > { Some (self . span_ext) . filter (| span | ! span . is_empty ()) } pub fn is_empty (& self) -> bool { self . args . is_empty () } }}}
